from test_bufftap import test, tests

R=("local B=BuffTap; playerClass='PRIEST'; spell(2006,'Resurrection'); B.db.reviveEnabled=true; "
 "GetNumSubgroupMembers=function() return 1 end; IsInRaid=function() return false end; "
 "local oldExists=UnitExists; UnitExists=function(u) return u=='party1' or oldExists(u) end; "
 "UnitIsPlayer=function() return true end; UnitIsConnected=function() return true end; "
 "dead={party1=true}; ghost={}; incoming={}; "
 "UnitIsDead=function(u) return dead[u]==true end; UnitIsGhost=function(u) return ghost[u]==true end; "
 "UnitHasIncomingResurrection=function(u) return incoming[u]==true end; "
 "local oldDG=UnitIsDeadOrGhost; UnitIsDeadOrGhost=function(u) if u=='player' then return false end return dead[u]==true or ghost[u]==true end; ")
test('Resurrection and Rebirth are off on a fresh profile',"assert(BuffTap.db.reviveEnabled==false and BuffTap.db.reviveRebirth==false)")
test('A dead group member gets your resurrection spell first',R+"refresh(); local a=B.action; assert(a and a.source=='revive' and a.target=='party1' and a.id==2006, a and a.source); assert(B.button.attrs.spell==2006 and B.button.attrs.unit=='party1')")
test('Released spirits are left alone',R+"ghost.party1=true; dead.party1=false; refresh(); assert(not (B.action and B.action.source=='revive'))")
test('Someone already being resurrected is skipped',R+"incoming.party1=true; refresh(); assert(not (B.action and B.action.source=='revive'))")
test('Turning resurrection off stops it',R+"B.db.reviveEnabled=false; refresh(); assert(not (B.action and B.action.source=='revive'))")
test('A dead player you target can be resurrected',R+"dead.party1=nil; dead.target=true; local oldIn=UnitInParty; UnitInParty=function(u) return false end; refresh(); assert(B.action and B.action.source=='revive' and B.action.target=='target')")
test('Rebirth is only offered when turned on',"local B=BuffTap; playerClass='DRUID'; spell(20484,'Rebirth'); GetNumSubgroupMembers=function() return 1 end; IsInRaid=function() return false end; local oldExists=UnitExists; UnitExists=function(u) return u=='party1' or oldExists(u) end; UnitIsPlayer=function() return true end; UnitIsDead=function(u) return u=='party1' end; UnitIsGhost=function() return false end; UnitHasIncomingResurrection=function() return false end; refresh(); assert(not (B.action and B.action.source=='revive')); B.db.reviveEnabled=true; B.db.reviveRebirth=true; refresh(); assert(B.action and B.action.source=='revive' and B.action.id==20484)")
test('A resurrection is dropped once they are alive again',R+"refresh(); local a=B.action; dead.party1=false; assert(not B:Validate(a))")
test('Cleanse page has the Resurrection row',R+"B:Options(); local f=B.options; assert(f.reviveEnable and f.reviveGroup and f.reviveTarget and f.reviveRebirth); B:UpdateCleansePage(); assert(not f.reviveRebirth.shown and f.reviveNote.text:find('Resurrection',1,true)); f.reviveEnable:SetChecked(false); f.reviveEnable.scripts.OnClick(f.reviveEnable); assert(B.db.reviveEnabled==false)")
test('Classes that cannot resurrect see a note',"local B=BuffTap; playerClass='MAGE'; spell(475,'Remove Lesser Curse'); B:Options(); B:UpdateCleansePage(); assert(B.options.reviveNote.text:find(\"can't resurrect\",1,true))")
test('Untrained Paladin can opt into resurrection and has no Abolish control',"local B=BuffTap; playerClass='PALADIN'; B:Options(); local f=B.options; assert(f.reviveNote.text=='Not learned yet'); assert(not f.cleanseAbolishInfo.shown); f.reviveEnable:SetChecked(true); f.reviveEnable.scripts.OnClick(f.reviveEnable); B:UpdateCleansePage(); assert(B.db.reviveEnabled==true and f.reviveEnable:GetChecked()); assert(not B:CanRevive()); spell(7328,'Redemption'); B:UpdateCleansePage(); assert(B:CanRevive() and f.reviveEnable:GetChecked() and f.reviveNote.text:find('Redemption'))")
test('Druid can configure unlearned Rebirth without overlapping status',"local B=BuffTap; playerClass='DRUID'; B:Options(); local f=B.options; B:UpdateCleansePage(); assert(f.reviveRebirth.shown,'switch visible'); assert(not f.reviveNote.shown); f.reviveRebirth:SetChecked(true); f.reviveRebirth.scripts.OnClick(f.reviveRebirth); assert(B.db.reviveRebirth and not B:ReviveSpell(true)); assert(f.cleanseFirst.shown)")
test('No incoming resurrection: a nil answer still offers the revive',R+"UnitHasIncomingResurrection=function() return nil end; refresh(); assert(B.action and B.action.source=='revive' and B.action.target=='party1')")
test('Incoming resurrection: true blocks, false allows',R+"UnitHasIncomingResurrection=function() return true end; refresh(); assert(not (B.action and B.action.source=='revive')); UnitHasIncomingResurrection=function() return false end; refresh(); assert(B.action and B.action.source=='revive')")
test('Incoming resurrection API error or odd value never offers a revive',R+"UnitHasIncomingResurrection=function() error('blocked') end; refresh(); assert(not (B.action and B.action.source=='revive')); UnitHasIncomingResurrection=function() return 'x' end; refresh(); assert(not (B.action and B.action.source=='revive'))")
test('Missing incoming-resurrection API keeps the old behaviour',R+"UnitHasIncomingResurrection=nil; refresh(); assert(B.action and B.action.source=='revive')")
from test_cleanse import S
RS=S+R+"spell(528,'Cure Disease'); debuff('player',7,'Plague','Disease',30); "
test('Revive comes before cleanse by default',RS+"refresh(); assert(B.action and B.action.source=='revive')")
test('Cleanse before resurrection puts the cleanse first',RS+"B.db.cleanseFirst=true; refresh(); assert(B.action and B.action.source=='cleanse')")
test('Cleanse-first still offers the revive when nothing needs cleansing',RS+"B.db.cleanseFirst=true; debuffs.player={}; B:InvalidateAura('player'); refresh(); assert(B.action and B.action.source=='revive')")
test('Revive-first still offers the cleanse when nobody is dead',RS+"dead.party1=nil; refresh(); assert(B.action and B.action.source=='cleanse')")
test('Cleanse before resurrection defaults off',"assert(BuffTap.db.cleanseFirst==false)")
test('Cleanse page shows the order checkbox only when the class can do both',RS+"B:Options(); local f=B.options; assert(f.cleanseFirst); B:UpdateCleansePage(); assert(f.cleanseFirst.shown); playerClass='ROGUE'; B:UpdateCleansePage(); assert(not f.cleanseFirst.shown)")
test('Cleanse order checkbox saves and survives a settings export and import',RS+"B:Options(); local f=B.options; B:UpdateCleansePage(); f.cleanseFirst:SetChecked(true); f.cleanseFirst.scripts.OnClick(f.cleanseFirst); assert(B.db.cleanseFirst==true); local text=B:ExportSettings(); B.db.cleanseFirst=false; assert(B:ImportSettings(text)); assert(B.db.cleanseFirst==true)")
test('1.24.7 unreadable connection state blocks resurrection', R+"UnitIsConnected=function() return nil end; refresh(); assert(not (BuffTap.action and BuffTap.action.source=='revive')); UnitIsConnected=function() return false end; refresh(); assert(not (BuffTap.action and BuffTap.action.source=='revive')); UnitIsConnected=function() return true end; refresh(); assert(BuffTap.action and BuffTap.action.source=='revive')")
test('1.24.7 range characterization: false blocks, true allows, unknown is the documented compatibility case',R+"C_Spell.IsSpellInRange=function() return false end; refresh(); assert(not (B.action and B.action.source=='revive'),'out of range'); C_Spell.IsSpellInRange=function() return true end; refresh(); assert(B.action and B.action.source=='revive','in range'); C_Spell.IsSpellInRange=function() return nil end; local r=B:SpellRange({id=2006,target='party1'}); assert(r==nil,'unknown stays unknown'); refresh(); assert(B.action and B.action.source=='revive','unknown range still offered: kept for Forever compatibility until verified in game')")
